// Format market cap
function formatMarketCap(value) {
    if (!value || isNaN(value)) return "N/A";
    if (value >= 1e12) return (value / 1e12).toFixed(2) + "T";
    if (value >= 1e9) return (value / 1e9).toFixed(2) + "B";
    if (value >= 1e6) return (value / 1e6).toFixed(2) + "M";
    return value.toLocaleString();
}

// Main visualization function
async function init() {
    // 1. Load Data
    const data = await d3.csv("data/stock-descriptions.csv", d => {
        return {
            ticker: d.ticker,
            name: d["full name"],
            sector: d.sector || "Unknown",
            marketCap: d.marketCap ? +d.marketCap : null,
            country: d.country,
            website: d.website
        };
    });

    // 2. Setup Chart Dimensions
    const container = document.getElementById("chart-container");
    const width = container.clientWidth;
    const height = container.clientHeight;

    const svg = d3.select("#chart-container")
        .append("svg")
        .attr("width", width)
        .attr("height", height)
        .attr("viewBox", [0, 0, width, height]);

    // 3. Process Data for Chart
    // Filter/Clean: ETFs might have empty sector or marketCap
    // Strategy: 
    // - Size: Sqrt scale for marketCap. If missing (ETF), use fixed size equivalent to ~50B or minimal.
    // - Grouping: Use Sector.

    const sectors = Array.from(new Set(data.map(d => d.sector))).sort();

    // Color Scale
    const colorScale = d3.scaleOrdinal()
        .domain(sectors)
        .range(d3.schemeTableau10); // Nice standard palette

    // Size Scale
    const maxCap = d3.max(data, d => d.marketCap);
    const radiusScale = d3.scaleSqrt()
        .domain([0, maxCap])
        .range([15, 60]); // Min 15px, Max 60px

    // Prepare nodes with initial radius
    const nodes = data.map(d => {
        const r = d.marketCap ? radiusScale(d.marketCap) : 20; // Default 20px for ETFs/No Cap
        return {
            ...d,
            radius: r,
            x: Math.random() * width,
            y: Math.random() * height
        };
    });

    // 4. Force Simulation
    // Create clusters: we want sectors to bunch together.
    // We can define a focal point for each sector.

    // Simple approach: Circle arrangement of foci
    const sectorFoci = {};
    sectors.forEach((sector, i) => {
        const angle = (i / sectors.length) * 2 * Math.PI;
        // Radius of the ring of clusters
        const ringRadius = Math.min(width, height) * 0.35; 
        sectorFoci[sector] = {
            x: width / 2 + Math.cos(angle) * ringRadius,
            y: height / 2 + Math.sin(angle) * ringRadius
        };
    });

    const simulation = d3.forceSimulation(nodes)
        .force("charge", d3.forceManyBody().strength(-10)) // Mild repulsion
        .force("collide", d3.forceCollide().radius(d => d.radius + 2).iterations(2)) // Prevent overlap
        .force("x", d3.forceX(d => sectorFoci[d.sector].x).strength(0.15)) // Pull to sector center
        .force("y", d3.forceY(d => sectorFoci[d.sector].y).strength(0.15));

    // 5. Render Bubbles
    const nodeGroup = svg.append("g")
        .selectAll("g")
        .data(nodes)
        .join("g")
        .attr("class", "node-group")
        .attr("cursor", "pointer")
        .call(d3.drag()
            .on("start", dragstarted)
            .on("drag", dragged)
            .on("end", dragended));

    const circles = nodeGroup.append("circle")
        .attr("class", "bubble")
        .attr("r", d => d.radius)
        .attr("fill", d => colorScale(d.sector))
        .attr("id", d => "bubble-" + d.ticker);

    const labels = nodeGroup.append("text")
        .attr("class", "bubble-label")
        .attr("dy", ".3em")
        .text(d => d.ticker)
        .attr("font-size", d => Math.min(14, d.radius / 1.5)); // Scale text slightly, max 14px

    // 6. Interactions (Tooltip & Highlight)
    const tooltip = d3.select("#tooltip");

    nodeGroup
        .on("mouseover", (event, d) => {
            // Check if ETF (missing marketCap usually implies ETF or similar in this dataset context)
            // User requirement: "ETF entries have no marketCap... do not show tooltip for them"
            if (d.marketCap === null) return;

            tooltip.classed("visible", true)
                .html(`
                    <strong>${d.ticker}</strong><br>
                    ${d.name}<br>
                    <span style="color:${colorScale(d.sector)}">●</span> ${d.sector}<br>
                    Cap: ${formatMarketCap(d.marketCap)}
                `)
                .style("left", (event.pageX + 15) + "px")
                .style("top", (event.pageY - 15) + "px");
        })
        .on("mousemove", (event) => {
            tooltip
                .style("left", (event.pageX + 15) + "px")
                .style("top", (event.pageY - 15) + "px");
        })
        .on("mouseout", () => {
            tooltip.classed("visible", false);
        })
        .on("click", (event, d) => {
            highlightStock(d.ticker);
        });

    // Simulation Tick
    simulation.on("tick", () => {
        nodeGroup.attr("transform", d => `translate(${d.x},${d.y})`);

        // Constrain to bounds (optional but good)
        nodes.forEach(d => {
            d.x = Math.max(d.radius, Math.min(width - d.radius, d.x));
            d.y = Math.max(d.radius, Math.min(height - d.radius, d.y));
        });
    });

    // Drag functions
    function dragstarted(event, d) {
        if (!event.active) simulation.alphaTarget(0.3).restart();
        d.fx = d.x;
        d.fy = d.y;
    }
    function dragged(event, d) {
        d.fx = event.x;
        d.fy = event.y;
    }
    function dragended(event, d) {
        if (!event.active) simulation.alphaTarget(0);
        d.fx = null;
        d.fy = null;
    }

    // 7. Render Legend
    const legendContainer = d3.select("#legend-container");
    sectors.forEach(sector => {
        const item = legendContainer.append("div").attr("class", "legend-item");
        item.append("div")
            .attr("class", "legend-color")
            .style("background-color", colorScale(sector));
        item.append("span").text(sector);
    });

    // 8. Render Table
    const tableDiv = d3.select("#table-container");
    const table = tableDiv.append("table");
    const thead = table.append("thead");
    const tbody = table.append("tbody");

    // Headers
    const columns = ["Ticker", "Full Company Name", "Sector", "Market Cap"];
    thead.append("tr")
        .selectAll("th")
        .data(columns)
        .join("th")
        .text(d => d);

    // Rows
    const rows = tbody.selectAll("tr")
        .data(data)
        .join("tr")
        .attr("id", d => "row-" + d.ticker)
        .on("click", (event, d) => {
            highlightStock(d.ticker);
        });

    rows.selectAll("td")
        .data(d => [
            d.ticker,
            d.name,
            d.sector,
            formatMarketCap(d.marketCap)
        ])
        .join("td")
        .text(d => d);

    // 9. Unification Function
    function highlightStock(ticker) {
        // Reset
        d3.selectAll(".bubble").classed("selected", false);
        d3.selectAll("tr").classed("selected", false);

        // Highlight Chart
        const bubble = d3.select("#bubble-" + ticker);
        bubble.classed("selected", true);

        // Highlight Table
        const row = d3.select("#row-" + ticker);
        row.classed("selected", true);

        // Scroll table to row
        const rowNode = row.node();
        if (rowNode) {
            rowNode.scrollIntoView({ behavior: "smooth", block: "center" });
        }
    }
}

// Run
init();

